mapper.select:
SELECT mass_email_id FROM crm_mass_email WHERE tenant_id = #{tenantId} AND deleted = 0
    AND status IN ('SCHEDULED', 'SENDING') AND scheduled_time <= #{now}
    AND EXISTS(SELECT 1 FROM crm_mass_email_recipient recipient WHERE recipient.tenant_id = #{tenantId}
        AND recipient.mass_email_id = crm_mass_email.mass_email_id AND recipient.test_flag = 0 AND recipient.status = 'PENDING')
ORDER BY scheduled_time, mass_email_id LIMIT #{limit}
